const items = $input.all();

const output = [];

for (const item of items) {
  const data = item.json;

  const views = Number(data.views ?? 0);
  const likes = Number(data.likes ?? 0);
  const comments = Number(data.comments ?? 0);

  const totalEngagement = likes + comments;

  const engagementRate =
    views > 0
      ? Number(((totalEngagement / views) * 100).toFixed(2))
      : 0;

  const likeRate =
    views > 0
      ? Number(((likes / views) * 100).toFixed(2))
      : 0;

  const commentRate =
    views > 0
      ? Number(((comments / views) * 100).toFixed(2))
      : 0;

  output.push({
    json: {
      ...data,

      total_engagement: totalEngagement,
      engagement_rate: engagementRate,
      like_rate: likeRate,
      comment_rate: commentRate
    }
  });
}

return output;

const items = $input.all();

const groups = new Map();

for (const item of items) {
  const data = item.json;

  const competitorId = data.competitorId;
  const competitorName = data.competitorName;
  const platform = data.platform;

  if (competitorId == null) {
    continue;
  }

  if (!groups.has(competitorId)) {
    groups.set(competitorId, {
      competitor_id: competitorId,
      competitor_name: competitorName ?? "",
      platform: platform ?? "",

      video_count: 0,

      total_views: 0,
      total_likes: 0,
      total_comments: 0,
      total_engagement: 0,

      total_like_rate: 0,
      total_comment_rate: 0
    });
  }

  const group = groups.get(competitorId);

  const views = Number(data.views ?? 0);
  const likes = Number(data.likes ?? 0);
  const comments = Number(data.comments ?? 0);
  const engagement = Number(data.total_engagement ?? 0);

  const likeRate = Number(data.like_rate ?? 0);
  const commentRate = Number(data.comment_rate ?? 0);

  group.video_count += 1;

  group.total_views += views;
  group.total_likes += likes;
  group.total_comments += comments;
  group.total_engagement += engagement;

  group.total_like_rate += likeRate;
  group.total_comment_rate += commentRate;
}

const output = [];

for (const group of groups.values()) {
  const videoCount = group.video_count;

  const averageViews =
    videoCount > 0
      ? Number((group.total_views / videoCount).toFixed(2))
      : 0;

  const averageLikes =
    videoCount > 0
      ? Number((group.total_likes / videoCount).toFixed(2))
      : 0;

  const averageComments =
    videoCount > 0
      ? Number((group.total_comments / videoCount).toFixed(2))
      : 0;

  const aggregateEngagementRate =
    group.total_views > 0
      ? Number(
          ((group.total_engagement / group.total_views) * 100).toFixed(2)
        )
      : 0;

  const averageLikeRate =
    videoCount > 0
      ? Number((group.total_like_rate / videoCount).toFixed(2))
      : 0;

  const averageCommentRate =
    videoCount > 0
      ? Number((group.total_comment_rate / videoCount).toFixed(2))
      : 0;

  output.push({
    json: {
      competitor_id: group.competitor_id,
      competitor_name: group.competitor_name,
      platform: group.platform,

      video_count: videoCount,

      total_views: group.total_views,
      total_likes: group.total_likes,
      total_comments: group.total_comments,
      total_engagement: group.total_engagement,

      average_views: averageViews,
      average_likes: averageLikes,
      average_comments: averageComments,

      engagement_rate: aggregateEngagementRate,
      average_like_rate: averageLikeRate,
      average_comment_rate: averageCommentRate
    }
  });
}

return output;

const items = $input.all();

const competitors = items.map(item => ({
  ...item.json
}));

// Xếp hạng theo engagement_rate giảm dần
competitors.sort(
  (a, b) =>
    Number(b.engagement_rate ?? 0) -
    Number(a.engagement_rate ?? 0)
);

const output = competitors.map((competitor, index) => ({
  json: {
    ...competitor,

    performance_rank: index + 1
  }
}));

return output;

const items = $input.all();

return items.map((item) => {
  const data = item.json;
  const errors = [];

  if (data.competitor_id == null) {
    errors.push("competitor_id không hợp lệ");
  }

  if (!data.competitor_name) {
    errors.push("competitor_name không hợp lệ");
  }

  if (!data.platform) {
    errors.push("platform không hợp lệ");
  }

  if (Number(data.video_count ?? 0) <= 0) {
    errors.push("video_count phải lớn hơn 0");
  }

  if (Number(data.total_views ?? -1) < 0) {
    errors.push("total_views không hợp lệ");
  }

  if (Number(data.total_likes ?? -1) < 0) {
    errors.push("total_likes không hợp lệ");
  }

  if (Number(data.total_comments ?? -1) < 0) {
    errors.push("total_comments không hợp lệ");
  }

  if (Number(data.total_engagement ?? -1) < 0) {
    errors.push("total_engagement không hợp lệ");
  }

  if (Number(data.engagement_rate ?? -1) < 0) {
    errors.push("engagement_rate không hợp lệ");
  }

  if (!Number.isInteger(Number(data.performance_rank))) {
    errors.push("performance_rank không hợp lệ");
  }

  return {
    json: {
      ...data,
      is_valid: errors.length === 0,
      validation_errors: errors
    }
  };
});

const items = $input.all();

return items.map((item) => {
  const data = item.json;

  return {
    json: {
      competitor_id: data.competitor_id ?? null,
      competitor_name: data.competitor_name ?? "",
      platform: data.platform ?? null,

      processing_status: "performance_invalid",

      validation_errors: Array.isArray(data.validation_errors)
        ? data.validation_errors
        : ["Performance data không hợp lệ"]
    }
  };
});
